def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foregrounds = [value for value in counts if value != background]
    if not foregrounds:
        return [row[:] for row in grid]
    foreground = max(foregrounds, key=lambda value: counts[value])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != foreground:
                continue
            left = c - 1
            while left >= 0 and grid[r][left] == background:
                left -= 1
            if left >= 0 and grid[r][left] == foreground:
                for x in range(left + 1, c):
                    out[r][x] = 2
            right = c + 1
            while right < w and grid[r][right] == background:
                right += 1
            if right < w and grid[r][right] == foreground:
                for x in range(c + 1, right):
                    out[r][x] = 2
            up = r - 1
            while up >= 0 and grid[up][c] == background:
                up -= 1
            if up >= 0 and grid[up][c] == foreground:
                for y in range(up + 1, r):
                    out[y][c] = 2
            down = r + 1
            while down < h and grid[down][c] == background:
                down += 1
            if down < h and grid[down][c] == foreground:
                for y in range(r + 1, down):
                    out[y][c] = 2
    return out

